let toastTimeout;function toast(message,undo) {const node=$('#toast');node.textContent=message;node.classList.toggle('has-action',Boolean(undo));if(undo){const button=document.createElement('button');button.type='button';button.className='toast-action';button.textContent=undo.label;button.onclick=()=>{clearTimeout(toastTimeout);node.classList.remove('visible','has-action');undo.run();};node.append(button);}node.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>node.classList.remove('visible','has-action'),undo?7000:3500);}
