function commitReviewedRoutine(routine,{replace=false,start=false}={}){if(recoveryRequired){toast('Restore your saved data before adding a template.');return false;}const result=commitRoutine(state,routine,{replace,start,storage:workoutStorage});if(!result.ok){if(['QuotaExceededError','SecurityError'].includes(result.error?.name)){storageError=true;restController.sync({...state,active:null},Date.now(),true);render();toast('Could not save. Your current data is unchanged. Export a backup or free device storage before trying again.');}else toast(result.error?.message||'Could not save this template. Your current data is unchanged.');return false;}state=result.state;storageError=false;restController.sync(state);return true;}
function commitStrongImport(preview){if(recoveryRequired||storageError||state.active){toast('Finish your workout and resolve storage recovery before importing.');return false;}const result=persistStrongImport(state,preview,{storage:workoutStorage});if(!result.ok){if(result.error?.name==='QuotaExceededError')throw new Error('Import could not be saved in Reptide’s available storage. Nothing changed. Keep your CSV and backup; very large histories may need a future storage upgrade.');if(result.error?.name==='SecurityError')throw new Error('Import could not be saved because local storage is unavailable. Nothing changed. Keep your CSV and backup, then try again when storage access returns.');throw result.error||new Error('Import could not be saved. Your current data is unchanged.');}state=result.state;storageError=false;tab='history';try{restController.sync(state);}catch{}return true;}
