function commitLogging(change,historyChange=false){if(storageError||recoveryRequired){toast('Resolve storage recovery before changing your workout.');return false;}try{const candidate={...structuredClone({...state,history:[]}),history:historyChange===true?structuredClone(state.history):typeof historyChange==='string'?state.history.map(w=>w.id===historyChange?structuredClone(w):w):state.history};change(candidate);workoutStorage.setState(candidate);state=candidate;restController.sync(state);queueAutoSync();return true;}catch(error){toast((error.name==='QuotaExceededError'||error.name==='SecurityError'||/storage|save account|stage workouts/i.test(error.message||''))?'Could not save. Your workout is unchanged.':error.message||'Could not save. Your workout is unchanged.');return false;}}
