 $('#app').innerHTML=`<div class="shell">${storageError?'<div class="storage-warning" role="alert">Local storage needs attention. Existing saved data has not been replaced. <button data-action="recover-export">Export saved data</button><button data-action="import">Restore backup</button><button data-action="retry-storage">'+(recoveryRequired?'Retry reading':'Retry saving')+'</button></div>':''}${state.active&&!navigation.minimized?sessionView():`${tab==='train'?trainView():tab==='history'?historyView():tab==='progress'?progressView():tab==='measure'?measureView(state,brand(),measurementChartPanel(state)):settingsView()}${state.active?resumeBar():''}${nav()}`}</div>`;
