function rememberNavigation(){navigation.tab=tab;writeNavigation(navigation);}
function captureInputDrafts(){if(!state.active||navigation.minimized)return;for(const input of document.querySelectorAll('[data-field]'))navigation.drafts[input.dataset.s+':'+input.dataset.field]={value:input.value,unit:state.settings.unit,invalid:input.getAttribute('aria-invalid')};}
function restoreInputDrafts(){if(!state.active||navigation.minimized)return;for(const input of document.querySelectorAll('[data-field]')){const draft=navigation.drafts[input.dataset.s+':'+input.dataset.field];if(draft&&typeof draft.value==='string'&&(input.dataset.field!=='weight'||draft.unit===state.settings.unit)){input.value=draft.value;input.setAttribute('aria-invalid',draft.invalid==='true'?'true':'false');}}}
function moveExercise(id,to){
 if(!state.active||storageError||recoveryRequired){toast('Resolve storage recovery before moving an exercise.');return;}
 captureInputDrafts();const from=state.active.exercises.findIndex(e=>e.id===id);
 if(from<0||!Number.isInteger(to)||to<0||to>=state.active.exercises.length){toast('Could not save the new order. Your workout is unchanged.');return;}
 // Save through the same validated store as every other logging edit, then publish.
 if(from!==to&&!commitLogging(next=>{const list=next.active.exercises;list.splice(to,0,list.splice(from,1)[0]);})){toast('Could not save the new order. Your workout is unchanged.');return;}
 rememberNavigation();render();const handle=[...document.querySelectorAll('[data-reorder-handle]')].find(n=>n.dataset.reorderHandle===id);handle?.focus({preventScroll:true});handle?.scrollIntoView({block:'nearest',behavior:'smooth'});toast('Exercise moved to position '+(to+1)+'.');
}
