function restIsForeground(){try{return typeof window.ForgeNative?.isRestForeground==='function'?window.ForgeNative.isRestForeground()===true:nativeForeground;}catch{return false;}}
function applyNativeRestAdjustment(){const change=restController.takeAdjustment();if(!change||!state.active||storageError||recoveryRequired||!applyRestAdjustment(structuredClone({id:state.active.id,restEndsAt:state.active.restEndsAt,restTotal:state.active.restTotal}),change))return false;return commitLogging(next=>{applyRestAdjustment(next.active,change);});}
function tick(){if(!state.active) return;const hold=state.active.setTimer;if(hold){const value=Math.floor(timerMilliseconds(hold)/1000);for(const node of document.querySelectorAll('[data-hold-time]'))if(node.dataset.holdTime===hold.setId)node.textContent=elapsed(value);if(hold.startedAt!==null){const input=[...document.querySelectorAll('[data-field="duration"],[data-field="walking-minutes"]')].find(n=>n.dataset.s===hold.setId);if(input)input.value=value?(input.dataset.field==='walking-minutes'?Math.round(value/60*1000)/1000:value):'';}}const now=Date.now(),node=$('#elapsed');if(node)node.textContent=elapsed(Math.max(0,Math.floor((now-state.active.startedAt)/1000)));const end=state.active.restEndsAt,rest=$('#rest-bar');const seconds=Math.max(0,Math.ceil((end-now)/1000));if(end&&seconds===0&&!document.hidden&&restIsForeground()&&applyNativeRestAdjustment())return tick();if(end&&seconds===0&&!document.hidden&&restIsForeground()&&commitLogging(next=>stopRest(next.active))){toast('Rest complete. Ready for your next set.');window.ForgeNative?.playRestEnd?.(`${state.active.id}:${end}`,state.settings.restAlertSound!==false);navigator.vibrate?.([100,50,100]);}const resumed=$('[data-resume-elapsed]');if(resumed)resumed.textContent=elapsed(Math.max(0,Math.floor((now-state.active.startedAt)/1000)))+' elapsed';const restCopy=$('[data-resume-rest]');if(restCopy)restCopy.textContent=end&&seconds>0?' · Rest '+elapsed(seconds):' · In progress';if(!rest)return;rest.innerHTML=end&&seconds>0?`<aside class="rest-timer" aria-label="Rest timer"><div class="rest-ring" style="--progress:${Math.min(1,seconds/(state.active.restTotal||90))*100}%">${icon('clock',22)}</div><span><small>REST TIMER</small><strong>${elapsed(seconds)}</strong></span><button data-action="extend-rest">+30s</button><button class="rest-skip" data-action="skip-rest">Skip ${icon('arrow',16)}</button></aside>`:'';}
