// iPhone edition: hand files to the iPhone share sheet (Save to Files, Save Image, AirDrop). Returns false when the
// share sheet can't take the file, so the caller falls back to a normal download.
function shareFile(blob,filename){try{const file=new File([blob],filename,{type:blob.type});if(!navigator.canShare?.({files:[file]}))return false;navigator.share({files:[file]}).catch(e=>{if(e?.name!=='AbortError')toast('Couldn’t open the share sheet. Try again.');});return true;}catch{return false;}}
