 'save-set-details':()=>{const type=$('#set-type').value,rpe=$('#set-rpe').value,entryId=modal.entryId,setId=modal.setId;if(!commitLogging(next=>{const set=next.active?.exercises.find(e=>e.id===entryId)?.sets.find(s=>s.id===setId);if(!set)throw new Error('Set no longer available.');if(type)set.setType=type;else delete set.setType;if(rpe)set.rpe=Number(rpe);else delete set.rpe;}))return;closeModal();render();},
